// One-off generator for test/fixtures/passkey-vectors.json (card bb86abf0, REFINE R4). Run once; its output
// is committed and never regenerated by the tests. It makes a throwaway P-256 key (the private half is never
// written anywhere), signs one valid passkey answer for a fixed grant plus one broken answer per safeguard,
// and records the OBSERVATORY RECORDER's verdict on each, by running the recorder's own approvalCheck().
// test/passkey-vectors.test.ts then requires the vault's copy (vault/src/passkey.ts) to give the same verdict.
//
// Usage: node test/fixtures/make-passkey-vectors.ts <dir holding observatory src/ at 7ddcffe> > test/fixtures/passkey-vectors.json
// (e.g. git -C <observatory clone> archive 7ddcffe src | tar -x -C <dir>)
import { pathToFileURL } from "node:url";

const dir = process.argv[2];
if (!dir) throw new Error("usage: make-passkey-vectors.ts <observatory dir>");
const { approvalCheck, grantHashOf } = await import(pathToFileURL(`${dir}/src/recorder/passkey.ts`).href);

const ORIGIN = "https://desk.example";
const RP = "desk.example";
const enc = new TextEncoder();
const b64u = (b: Uint8Array) => Buffer.from(b).toString("base64url");
const digest = async (b: Uint8Array | string) => new Uint8Array(await crypto.subtle.digest("SHA-256", typeof b === "string" ? enc.encode(b) : b));
const hex = (b: Uint8Array) => Buffer.from(b).toString("hex");

function rawToDer(raw: Uint8Array): Uint8Array {
  const int = (v: Uint8Array) => {
    let i = 0;
    while (i < 31 && v[i] === 0) i++;
    v = v.slice(i);
    return v[0] & 0x80 ? [0x02, v.length + 1, 0, ...v] : [0x02, v.length, ...v];
  };
  const body = [...int(raw.slice(0, 32)), ...int(raw.slice(32))];
  return new Uint8Array([0x30, body.length, ...body]);
}

const pair = (await crypto.subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, false, ["sign", "verify"])) as CryptoKeyPair;
const jwk = (await crypto.subtle.exportKey("jwk", pair.publicKey)) as JsonWebKey;
const x = Buffer.from(jwk.x!, "base64url"), y = Buffer.from(jwk.y!, "base64url");
const cose = new Uint8Array([0xa5, 0x01, 0x02, 0x03, 0x26, 0x20, 0x01, 0x21, 0x58, 0x20, ...x, 0x22, 0x58, 0x20, ...y]);
const ID = "vectors-passkey-1";
const pin = { id: ID, key: b64u(cose), rp_hash: hex(await digest(RP)), origin_hash: hex(await digest(ORIGIN)) };

const grant = { id: "g-vectors-0001", job: "cf.zone.read", params: { zone: "benculbert.com" }, requester: "c-box agent", expires_at: 1793000000000 };
const asRecord = (g: typeof grant) => ({ v: 1, grant: g.id, stage: "request", job: g.job, params: g.params, requester: g.requester, expires_at: g.expires_at });
const grantHash: string = await grantHashOf(asRecord(grant));
const otherHash: string = await grantHashOf(asRecord({ ...grant, id: "g-vectors-0002" }));

type Opts = { origin?: string; rp?: string; flags?: number; type?: string; id?: string; hash?: string; client?: object; der?: (d: Uint8Array) => Uint8Array; challengeBytes?: number };
async function answer(o: Opts = {}) {
  const random = crypto.getRandomValues(new Uint8Array(o.challengeBytes ?? 16));
  const challenge = new Uint8Array([...random, ...Buffer.from(o.hash ?? grantHash, "hex")]);
  const clientData = enc.encode(JSON.stringify({ type: o.type ?? "webauthn.get", challenge: b64u(challenge), origin: o.origin ?? ORIGIN, crossOrigin: false, ...o.client }));
  const auth = new Uint8Array([...(await digest(o.rp ?? RP)), o.flags ?? 0x05, 0, 0, 0, 0]);
  const raw = new Uint8Array(await crypto.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, pair.privateKey, new Uint8Array([...auth, ...(await digest(clientData))])));
  const der = rawToDer(raw);
  return { passkey_id: o.id ?? ID, authenticator_data: b64u(auth), client_data_json: b64u(clientData), signature: b64u(o.der ? o.der(der) : der) };
}

const valid = await answer();
const otherSig = (await answer()).signature; // a valid signature, but over different bytes
const cases: { name: string; assertion: unknown }[] = [
  { name: "valid", assertion: valid },
  { name: "wrong passkey id", assertion: { ...valid, passkey_id: "someone-else" } },
  { name: "wrong origin", assertion: await answer({ origin: "https://evil.example" }) },
  { name: "cross-origin frame", assertion: await answer({ client: { crossOrigin: true } }) },
  { name: "top origin set", assertion: await answer({ client: { topOrigin: "https://evil.example" } }) },
  { name: "wrong rp", assertion: await answer({ rp: "evil.example" }) },
  { name: "no user verification (no Face ID)", assertion: await answer({ flags: 0x01 }) },
  { name: "backed up without backup-eligible", assertion: await answer({ flags: 0x15 }) },
  { name: "attested data flag on a sign-in", assertion: await answer({ flags: 0x45 }) },
  { name: "registration, not sign-in", assertion: await answer({ type: "webauthn.create" }) },
  { name: "signature over other bytes", assertion: { ...valid, signature: otherSig } },
  { name: "another grant's hash", assertion: await answer({ hash: otherHash }) },
  { name: "challenge of the wrong length", assertion: await answer({ challengeBytes: 15 }) },
  { name: "malformed DER signature", assertion: await answer({ der: (d) => new Uint8Array([...d, 0]) }) },
  { name: "missing signature", assertion: { passkey_id: valid.passkey_id, authenticator_data: valid.authenticator_data, client_data_json: valid.client_data_json } },
];

const check = approvalCheck(pin);
const out = [];
for (const c of cases) {
  const verdict = await check({ v: 1, grant: grant.id, stage: "approval", job: grant.job, assertion: c.assertion }, grantHash);
  out.push({ ...c, verdict: verdict ?? null });
}
process.stdout.write(
  JSON.stringify(
    { made_by: "test/fixtures/make-passkey-vectors.ts", verdicts_from: "weird-ways-observatory/observatory src/recorder/passkey.ts approvalCheck() @7ddcffe", origin: ORIGIN, rp: RP, pin, grant, grant_hash: grantHash, cases: out },
    null,
    1,
  ) + "\n",
);
